(itemID)\n      if tooltip then\n         for i = #tooltip.lines, 1, -1 do\n            if tooltip.lines[i].leftText and tooltip.lines[i].leftText:find(ITEM_SPELL_KNOWN, 1, true)\n            or tooltip.lines[i].rightText and tooltip.lines[i].rightText:find(ITEM_SPELL_KNOWN, 1, true) then\n               has = true\n               break\n            end\n         end\n      end   \n   end\n   if has == false then for k in pairs(slotsUnlearned) do print(k) end end\n   return has, count, slots\nend\n\nsetLoader:AddContinuable(Item:CreateFromItemID(itemID))\nsetLoader:ContinueOnLoad(function()\n      print(hasEnsemble(itemID))\n      \nend)\n",
